#!/bin/bash
# Mesh a case generated by setup_case.py (4 MPI ranks). Usage: mesh_case.sh <case_dir>
source /usr/lib/openfoam/openfoam2512/etc/bashrc
set -e
export OMPI_MCA_btl_vader_single_copy_mechanism=none
cd "$1"
blockMesh > log.blockMesh 2>&1
surfaceFeatureExtract > log.surfaceFeatureExtract 2>&1
decomposePar -force > log.decomposePar.mesh 2>&1
mpirun --allow-run-as-root --oversubscribe -np 4 snappyHexMesh -parallel -overwrite > log.snappyHexMesh 2>&1
mpirun --allow-run-as-root --oversubscribe -np 4 checkMesh -parallel -constant > log.checkMesh 2>&1 || true
# fresh initial fields on every processor
for p in processor*; do rm -rf $p/0; cp -r 0.orig $p/0; done
mpirun --allow-run-as-root --oversubscribe -np 4 patchSummary -parallel > log.patchSummary 2>&1 || true
